update pages set contenu = '{"sections":[{"type":"heros","h1":"Maintenance industrielle à Avignon et dans le Vaucluse","mecanisme":"Le Vaucluse vit au rythme des fruits et légumes. Marché d''intérêt national d''Avignon, stations de conditionnement de Cavaillon et de Carpentras, entrepôts de Courtine du couloir rhodanien : la saison commande tout. À côté, les procédés continus de Sorgues n''admettent aucune improvisation. Nos techniciens itinérants couvrent le bassin et se déplacent partout en France.","cta":"Demander une intervention à Avignon","telephone":"04 78 33 72 05","phraseDelai":"Nous vous rappelons dans l''heure, du lundi au vendredi de 8h00 à 18h30. L''astreinte 24/24 et 7/7 couvre les nuits, les week-ends et les jours fériés."},{"type":"chiffres","chiffres":[{"valeur":"+ 120","libelle":"clients industriels accompagnés, dont plus de 80 réguliers"},{"valeur":"10 %","libelle":"des candidats retenus, entretien technique et comportemental"},{"valeur":"4","libelle":"agences, Lyon (siège), Montréal, Dubaï, Madrid, et des techniciens mobiles partout en France"}]},{"type":"probleme","punchline":"La calibreuse s''arrête en pleine campagne de conditionnement. Les palettes continuent d''arriver, et le fruit ne se stocke pas.","puces":[{"accroche":"La saison commande, pas le calendrier de maintenance.","texte":"Un arrêt en campagne coûte du produit perdu, pas seulement des heures de main d''œuvre."},{"accroche":"Un rouleau bloqué fige un entrepôt entier.","texte":"Sur les plateformes de Courtine, la manutention ne supporte pas l''à-peu-près."},{"accroche":"La chimie ne laisse pas entrer n''importe qui.","texte":"Consignation, permis de feu, espaces confinés : un prestataire sans le cadre écrit est un risque, pas une aide."},{"accroche":"Le préventif saute dès que la charge monte.","texte":"Il revient toujours plus tard, sous forme de casse."},{"accroche":"Le bon technicien est déjà chez le voisin.","texte":"Le bassin recrute en agro, en logistique et en mécanique en même temps."}]},{"type":"offre","lignes":[{"prestation":"**Préventif calé sur la campagne**, resserré avant la saison et allégé pendant les creux.","benefice":"Les révisions tombent quand la ligne est disponible, pas quand elle casse."},{"prestation":"**Dépannage sur site** avec recherche de cause racine, du motoréducteur à l''armoire électrique.","benefice":"Le même défaut ne revient pas trois fois dans l''année."},{"prestation":"**Cadre de sécurité écrit avant l''intervention** : plan de prévention, consignation, permis de travail.","benefice":"Vos sites classés accueillent une équipe qui connaît les règles avant d''arriver."},{"prestation":"**Convoyeurs, quais et systèmes de tri** des plateformes : voir la [maintenance équipements logistiques](/secteurs/logistique/).","benefice":"Un seul contrat du quai de réception au quai d''expédition."},{"prestation":"**Automatisme et variation de vitesse** : SIEMENS et Schneider, lecture des codes défaut, défauts intermittents.","benefice":"L''automate qui bloque trouve quelqu''un capable de le lire."},{"prestation":"**Froid industriel et utilités** : échangeurs, réseaux d''air, réseaux d''eau, chasse aux fuites.","benefice":"La dérive thermique se corrige avant de se voir dans le produit."},{"prestation":"**Astreinte 24/24 et 7/7 en option**, mobilisation de techniciens mobiles partout en France.","benefice":"Une panne du week-end en pleine campagne trouve un interlocuteur."},{"prestation":"**Technicien en [Résidence](/offres/residence/)** intégré à votre équipe, prise de poste en 2 à 3 semaines.","benefice":"Le poste que vous n''arrivez pas à pourvoir est tenu, remplacement assuré."}],"prose":[{"texte":"Pour une mise en service, un transfert de ligne ou une extension, notre offre [chantier](/offres/chantier/) prend le relais avec un chef de projet unique."}]},{"type":"deroule","etapes":[{"titre":"Premier contact","texte":"vous décrivez la panne ou le projet. Un chargé d''affaires rappelle dans l''heure aux horaires ouvrés."},{"titre":"Qualification","texte":"machines, accès au site, habilitations, contraintes d''hygiène et de sécurité. Tout se note avant le chiffrage."},{"titre":"Devis écrit","texte":"périmètre, créneaux, matériel, conditions horaires. L''exceptionnel se chiffre en amont."},{"titre":"Intervention","texte":"accueil sécurité, plan de prévention, consignation, diagnostic, réparation, redémarrage sécurisé."},{"titre":"Compte rendu","texte":"opérations, temps passé, pièces à prévoir, préconisations, versés dans votre GMAO."},{"titre":"Suivi","texte":"sur contrat, revue de la disponibilité et de la récurrence, équipement par équipement."}]},{"type":"garanties","puces":[{"accroche":"Le profil vous est présenté avant l''intervention.","texte":"Entretien technique et comportemental, 10 % des candidats retenus, habilitations à jour vérifiées."},{"accroche":"Le cadre de sécurité précède le travail.","texte":"Plan de prévention, consignation, permis de feu et règles d''espaces confinés se traitent en préalable, pas en option."},{"accroche":"Le périmètre et la sortie sont écrits.","texte":"Inclus, exclu, conditions d''astreinte, conditions d''arrêt. Le cadre protège les deux parties."}]},{"type":"cta","question":"Besoin de passer la prochaine campagne sans arrêt subi ?","bouton":"Demander une intervention à Avignon","rappel":"Ou appelez le 04 78 33 72 05, du lundi au vendredi de 8h00 à 18h30. Rappel dans l''heure."},{"type":"preuves","preuves":[{"titre":"2 techniciens intégrés en 3x8 sur des lignes de nutrition infantile","texte":", liquides et conditionnement poudre","lienLibelle":"Étude de cas DANONE : lignes de production","lienHref":"/preuves/danone-lignes-de-production/"},{"titre":"Renfort de 6 mois sur un site de traitement des eaux industrielles à risque chimique","texte":", avec habilitation dédiée","lienLibelle":"Étude de cas SUEZ : remise en état d''un site","lienHref":"/preuves/suez-remise-en-etat/"},{"titre":"6 techniciens polyvalents en permanence sur un contrat de préventif annuel logistique","texte":", reprise complète en un mois","lienLibelle":"Étude de cas VEEPEE : sites de Lyon","lienHref":"/preuves/veepee-sites-lyon/"},{"titre":"Un technicien en renfort pendant les congés d''été","texte":", pour tenir les équipements en juillet et août","lienLibelle":"Étude de cas OGF : arrêt estival","lienHref":"/preuves/ogf-arret-estival/"}]},{"type":"objections","questions":[{"question":"Intervenez-vous vraiment dans le Vaucluse, alors que votre siège est à Lyon ?","reponse":"Oui. Nous n''avons pas d''agence à Avignon et nous ne l''inventons pas : nos techniciens se déplacent partout en France et interviennent sur site. Votre demande est rappelée dans l''heure aux horaires ouvrés, et vous savez dès le premier appel si le besoin est tenable."},{"question":"Quelles communes couvrez-vous ?","reponse":"Avignon et Le Pontet, la zone de Courtine, Sorgues, Cavaillon, Carpentras et les zones d''activité de la périphérie. Au-delà, le relais passe au réseau national."},{"question":"Vos techniciens peuvent-ils intervenir sur un site classé ?","reponse":"Oui, avec le cadre : plan de prévention, consignation, permis de feu, permis de travail, règles d''espaces confinés. Le point se fait à la qualification, avant le devis, jamais sur place."},{"question":"Pouvez-vous intervenir uniquement en campagne, quelques semaines par an ?","reponse":"Oui. Le renfort saisonnier se prépare en amont : état des lieux, pièces critiques identifiées, créneaux réservés. Le préventif se resserre avant la montée en charge."},{"question":"Combien coûte un contrat de maintenance ?","reponse":"L''offre Zéro arrêt fonctionne en abonnement, trois niveaux de couverture, sur devis, engagement type 6 mois renouvelable, diagnostic gratuit au départ."},{"question":"Pouvez-vous reprendre un contrat existant ?","reponse":"Oui. Reprise de l''historique, connexion à vos données d''arrêt, phase de recouvrement avec le prestataire sortant. La chaîne de responsabilité reste nette pendant la bascule."}]},{"type":"ctaFinal","question":"Besoin de fiabiliser vos lignes avant la montée en charge ?","bouton":"Demander une intervention à Avignon","rappel":"ou appelez le 04 78 33 72 05, rappel dans l''heure aux horaires ouvrés."}]}'::jsonb where path = '/implantations/maintenance-industrielle-avignon/';
